import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the committed solver-parity corpus (generated by the Elixir
/// `color_matching` service from `ColorMatching.WeightedSquaredError`) through
/// `WeightedSquaredErrorScorer` and `CompositionSolver`, asserting exact
/// agreement on scores, selections, tie-breaking, and exclusions.
///
/// The fixture at `Fixtures/parity-v1-corpus.json` is a byte-identical copy of
/// `priv/parity/v1/corpus.json` from viamin/color_matching. Refresh it (and the
/// expected `algorithm_version`) whenever the server corpus regenerates — see
/// `docs/solver-parity-corpus.md`.
final class SolverParityCorpusTests: XCTestCase {
    private let scorer = WeightedSquaredErrorScorer()

    // MARK: - Corpus stamps

    func testCorpusStampsMatchSharedContract() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1, "corpus algorithm_version must match the parity contract this suite enforces")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
    }

    func testCorpusFixtureIntegrity() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.scenarios.count, 12, "scenario set changed — refresh the fixture and review parity impact")
        XCTAssertEqual(Set(corpus.scenarios.map(\.id)).count, corpus.scenarios.count, "scenario ids must be unique")

        for scenario in corpus.scenarios {
            XCTAssertEqual(
                scenario.palette.compactMap(\.index),
                Array(scenario.palette.indices),
                "\(scenario.id): palette entries must be indexed 0..<n in order"
            )
            for vector in scenario.palette + [scenario.target] {
                XCTAssertNotNil(RGBColor(hex: vector.hexColor), "\(scenario.id): unparseable hex \(vector.hexColor)")
            }
        }
    }

    func testCorpusContainsTieAndNoSelectionScenarios() throws {
        let corpus = try loadCorpus()

        XCTAssertGreaterThanOrEqual(corpus.scenarios.filter { $0.expected.tieBroke == true }.count, 1, "corpus must exercise tie-breaking")
        XCTAssertGreaterThanOrEqual(corpus.scenarios.filter { $0.expected.selectedIndex == nil }.count, 1, "corpus must exercise all-excluded targets")
    }

    // MARK: - Scenario replay

    func testScorerScoresAndSelectionsMatchCorpusExactly() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let replay = try replayScenario(scenario)

            XCTAssertEqual(
                replay.results.count, scenario.expected.scores.count,
                "\(scenario.id): scored candidate count must cover the whole palette"
            )
            for expectedScore in scenario.expected.scores {
                assertResult(replay.results[expectedScore.index], matches: expectedScore.score, scenario: scenario.id, index: expectedScore.index)
            }

            switch (replay.bestIndex, scenario.expected.selectedIndex) {
            case (nil, nil):
                XCTAssertNil(scenario.expected.error, "\(scenario.id): no-selection scenarios carry no error")
            case (let index?, let expectedIndex?):
                XCTAssertEqual(index, expectedIndex, "\(scenario.id): selected index")
                XCTAssertEqual(replay.palette[index].hex, scenario.expected.selectedHexColor, "\(scenario.id): selected hex color")
                if let expectedError = scenario.expected.error {
                    XCTAssertEqual(replay.bestScore!, expectedError, accuracy: 1e-12, "\(scenario.id): selected error")
                } else {
                    XCTFail("\(scenario.id): expected an error alongside selected index \(expectedIndex)")
                }
            default:
                XCTFail("\(scenario.id): selection mismatch — replay picked \(String(describing: replay.bestIndex)), corpus expects \(String(describing: scenario.expected.selectedIndex))")
            }
        }
    }

    func testTieEvidenceMatchesCorpus() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let replay = try replayScenario(scenario)
            let expected = scenario.expected

            guard let bestScore = replay.bestScore else {
                XCTAssertNil(expected.tieBroke, "\(scenario.id): tie_broke must be null when nothing is selectable")
                XCTAssertEqual(expected.tiedIndices, [], "\(scenario.id): no ties when nothing is selectable")
                continue
            }

            let recomputedTies = replay.results.enumerated().compactMap { entry -> Int? in
                guard case .score(let value) = entry.element else { return nil }
                return abs(value - bestScore) <= 1e-12 ? entry.offset : nil
            }

            XCTAssertEqual(recomputedTies, expected.tiedIndices, "\(scenario.id): tied index set")
            XCTAssertEqual(expected.tieBroke, recomputedTies.count > 1, "\(scenario.id): tie_broke flag")
            XCTAssertEqual(recomputedTies.first, expected.selectedIndex, "\(scenario.id): earliest tied index must be the selection")
        }
    }

    /// Drives the production solver (1×1 grids, one per active condition) so
    /// parity covers the app's real selection path, not just the scorer.
    ///
    /// Scenarios whose *target* is missing a positive-weight channel are
    /// scorer-level only: the solver always builds complete target vectors from
    /// source grids, so a target-side gap cannot arise through `solve`.
    func testSolverEndToEndMatchesCorpusSelections() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let replay = try replayScenario(scenario)

            let targetComplete = replay.weights.activeEntries.allSatisfy { replay.target.value(for: $0.condition) != nil }
            if !targetComplete {
                XCTAssertNil(scenario.expected.selectedIndex, "\(scenario.id): only all-excluded selections are expected with an incomplete target")
                continue
            }

            var grids: [LightingCondition: BrightnessGrid] = [:]
            for entry in replay.weights.activeEntries {
                grids[entry.condition] = BrightnessGrid(width: 1, height: 1, fill: replay.target.value(for: entry.condition)!)
            }

            let result = try CompositionSolver(scorer: WeightedSquaredErrorScorer())
                .solve(palette: replay.palette, sourceGrids: grids, weights: replay.weights)

            XCTAssertEqual(result.colorIndices.first.flatMap { $0 }, scenario.expected.selectedIndex, "\(scenario.id): solver selection")
            if let expectedError = scenario.expected.error {
                XCTAssertEqual(result.errors.first ?? .infinity, expectedError, accuracy: 1e-12, "\(scenario.id): solver error")
            } else {
                XCTAssertEqual(result.errors.first?.isInfinite, true, "\(scenario.id): unmatched cell must record infinite error")
            }
        }
    }

    /// The corpus weights map may carry light sources outside the canonical
    /// five (see the `unknown-weight-ignored` scenario); they must not affect
    /// matching.
    func testUnknownWeightKeysAreIgnored() throws {
        let scenario = try XCTUnwrap(try loadCorpus().scenarios.first { $0.id == "unknown-weight-ignored" })

        let canonical = scenario.weights.filter { LightingCondition(rawValue: $0.key) != nil }

        XCTAssertEqual(channelWeights(from: scenario.weights), channelWeights(from: canonical))
        XCTAssertEqual(scenario.weights.keys.count, canonical.keys.count + 1, "scenario must actually carry an unknown key")
    }

    // MARK: - Replay plumbing

    private struct ScenarioReplay {
        let palette: [PaletteColor]
        let target: TargetResponseVector
        let weights: ChannelWeights
        let results: [ScorerResult]
        let bestIndex: Int?
        let bestScore: Double?
    }

    private func replayScenario(_ scenario: ParityScenario) throws -> ScenarioReplay {
        let palette = scenario.palette.map { domainColor(from: $0) }
        let target = TargetResponseVector(
            Dictionary(
                uniqueKeysWithValues: scenario.target.channels.compactMap { key, value in
                    LightingCondition(rawValue: key).map { ($0, value) }
                }
            )
        )
        let weights = channelWeights(from: scenario.weights)

        let results = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }

        var bestIndex: Int?
        var bestScore: Double?
        for (index, result) in results.enumerated() {
            guard case .score(let value) = result else { continue }
            if bestScore == nil || value < bestScore! {
                bestScore = value
                bestIndex = index
            }
        }

        return ScenarioReplay(
            palette: palette,
            target: target,
            weights: weights,
            results: results,
            bestIndex: bestIndex,
            bestScore: bestScore
        )
    }

    private func domainColor(from vector: ParityVector) -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(
            id: vector.index ?? -1,
            hex: vector.hexColor,
            rgb: RGBColor(hex: vector.hexColor) ?? RGBColor(red: 0, green: 0, blue: 0),
            responses: responses
        )
    }

    private func channelWeights(from raw: [String: Double]) -> ChannelWeights {
        var weights = ChannelWeights()
        for condition in LightingCondition.all {
            guard let value = raw[condition.rawValue] else { continue }
            switch condition {
            case .white: weights.white = value
            case .red: weights.red = value
            case .green: weights.green = value
            case .blue: weights.blue = value
            case .lps: weights.lps = value
            }
        }
        return weights
    }

    private func assertResult(
        _ result: ScorerResult,
        matches expected: ParityScoreValue,
        scenario: String,
        index: Int
    ) {
        switch (result, expected) {
        case (.excluded, .excluded):
            return
        case (.score(let actual), .value(let expectedValue)):
            XCTAssertEqual(actual, expectedValue, accuracy: 1e-12, "\(scenario): candidate \(index) score")
        default:
            XCTFail("\(scenario): candidate \(index) expected \(expected), got \(result)")
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: try fixtureData("parity-v1-corpus.json"))
    }

    private func fixtureData(_ name: String) throws -> Data {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("Fixtures", isDirectory: true)
            .appendingPathComponent(name)
        return try Data(contentsOf: url)
    }
}

// MARK: - Corpus wire model

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let lightSources: [String]
    let missingPolicy: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let description: String
    let palette: [ParityVector]
    let target: ParityVector
    let weights: [String: Double]
    let expected: ParityExpectation
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]
}

private struct ParityExpectation: Decodable {
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
    let scores: [ParityScore]
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue
}

/// The corpus encodes a candidate outcome as a JSON number, or the string
/// `"excluded"` when the candidate is unrankable.
private enum ParityScoreValue: Equatable, Decodable {
    case value(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let number = try? container.decode(Double.self) {
            self = .value(number)
        } else if let text = try? container.decode(String.self), text == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "parity score must be a number or \"excluded\""
            )
        }
    }
}
